<script setup>
import {Head,Link,useForm} from '@inertiajs/vue3';import AdminLayout from '../Components/AdminLayout.vue';import {ArrowLeft,Save,Ticket} from '@lucide/vue';
const props=defineProps({type:String,record:Object});const label=props.type==='coupon'?'Coupon':'Gift card';const endpoint=props.type==='coupon'?'/admin/coupons':'/admin/gift-cards';const form=useForm({name:props.record?.name||'',code:props.record?.code||'',amount:props.record?.amount||'',status:props.record?.status??true});
function save(){if(props.record)form.put(endpoint+'/'+props.record.id);else form.post(endpoint);}
</script>
<template><Head :title="(record?'Edit ':'Create ')+label"/><AdminLayout :title="label"><div class="page-heading"><div><span class="eyebrow">CHECKOUT DISCOUNTS</span><h1>{{ record?'Edit':'Create' }} {{ label.toLowerCase() }}</h1><p>Save a fixed BDT discount for checkout.</p></div><Link :href="endpoint" class="btn secondary"><ArrowLeft :size="16"/>Back</Link></div><section class="panel discount-editor" style="max-width:850px"><h2><Ticket :size="20"/>{{ label }} details</h2><form @submit.prevent="save"><div class="discount-fields" style="grid-template-columns:repeat(2,minmax(0,1fr))"><label>Name<input v-model="form.name" maxlength="150" required/><small>{{ form.errors.name }}</small></label><label>{{ type==='coupon'?'Coupon number / code':'Gift card code' }}<input v-model="form.code" maxlength="60" required placeholder="e.g. WELCOME100"/><small>{{ form.errors.code }}</small></label><label>Amount (BDT)<input v-model="form.amount" type="number" min="0.01" max="99999999.99" step="0.01" required/><small>{{ form.errors.amount }}</small></label><label>Status<select v-model="form.status"><option :value="true">Active</option><option :value="false">Inactive</option></select><small>{{ form.errors.status }}</small></label></div><p class="discount-hint">Customers enter the code at checkout. Inactive codes cannot be used. Discount applies to products; delivery is separate.</p><div class="discount-actions"><Link :href="endpoint" class="btn secondary">Cancel</Link><button class="btn primary" :disabled="form.processing"><Save :size="16"/>{{ form.processing?'Saving…':'Save '+label.toLowerCase() }}</button></div></form></section></AdminLayout></template>
<style scoped>.discount-editor,.discount-list{padding:24px;margin-bottom:22px;border-radius:16px}.discount-editor h2{display:flex;gap:10px;font-weight:700;margin-bottom:20px}.discount-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.discount-fields label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:600}.discount-fields input,.discount-fields select{padding:11px;border:1px solid #dce5df;border-radius:8px;background:white;font:inherit}.discount-fields small{color:#ae3549}.discount-actions{display:flex;gap:10px;margin-top:18px}.discount-hint{font-size:12px;color:#75847c;line-height:1.7;margin-top:16px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:15px 12px;border-bottom:1px solid #edf0ee;white-space:nowrap}td button{padding:7px;display:inline-flex;color:#577465}.active,.inactive{padding:5px 9px;border-radius:6px;background:#e8f5ed;color:#267752}.inactive{background:#f4ebee;color:#a54459}@media(max-width:900px){.discount-fields{grid-template-columns:1fr 1fr}}@media(max-width:500px){.discount-fields{grid-template-columns:1fr}.discount-editor,.discount-list{padding:18px}}@media(max-width:500px){.discount-fields{grid-template-columns:1fr!important}}</style>
